function [y] = field_switch(on, ht, tq)
%FIELD_SWITCH  Whether the field is on after this step: on before, the target's share of capacity ht and the command's share of the
%   largest torque tq.
%   on: bool (passed true or false)
%   ht: real[1] (passed a plain number)
%   tq: real[1] (passed a plain number)
%   returns y: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = false;
    y = on;
    if ((ht > 0.02) || (tq > 0.02))
        y = true;
    elseif ((ht < 0.01) && (tq < 0.01))
        y = false;
    end
end
